space {
  id = "beer_hall",
  region = "far_enough",
  name = "The Second Shift",
  description = "The biggest tavern in Far Enough, named for when it gets busy. Long tables, a low ceiling, stone mugs with lids. The beer is black and comes with a spoon. At the end of every table somebody is singing, and it is the same song at all of them, at different verses.",
  palette = { bg = "#120c08", text = "#d8ccb8", dim = "#76685a", accent = "#e0a050", border = "#4c3622" },
  ambience = {
    flicker { color = "#e0a050", strength = 0.18 },
    steam { glyphs = "∙°˙", color = "#6a5c50", rate = 0.3 },
  },

  things = {
    { name = "Old Pebble",
      key = "pebble",
      icon = "☺",
      description = "A very old dwarf by himself at the end of the last table, with a small mug. His beard is white to the floor. He is the only dwarf in the hall with his back to the wall and his face to the door, and the only one not singing.",
      variants = {
        { when = flag "fe_pick_returned",
          description = "A very old dwarf at the end of the last table, with a small mug and his chair turned to the room. He is singing. He has a thin, true voice, a verse behind everybody else, and the whole hall has slowed down so that he can catch up. Nobody is looking at him. Every dwarf in the place is listening with the back of the head.",
          actions = {
            { "Sit with him", say "He moves his mug to make room. He does not stop singing. At the chorus he nods you in, and you sing {i}down{/} eleven times beside him, and on the twelfth he hums, and so do you, and it is a perfectly good verse." },
            { "Ask how the pick looks", say "\"Fits,\" he says. And then, because he is a dwarf and that was nearly gushing, he looks into his mug. \"I drew the outline a bit big,\" he says. \"I remembered it bigger.\"" },
          } },
        { when = flag "fe_pebble_trusts",
          description = "He has turned his chair round to face the room. It is the first time, the landlord says, since before the landlord. He is not singing. But he is tapping the table at the chorus." },
      },
      things = {
        { name = "his small mug", description = "Half the size of the others, with no lid. He had the lid taken off, long ago. He said he had had enough of things being shut over him.",
          variants = {
            { when = flag "fe_pick_returned", description = "Half the size of the others, with no lid. It is full, and it is not his first, and the landlord is not putting them on the slate." },
          } },
        { name = "his beard", description = "White, uncut, and coiled twice on the floor beside his chair. A dwarf's beard is plaited for his trade. His is loose. He was never passed out of his apprenticeship. Nobody knew who should sign it." },
        { name = "his hands", description = "Small, for a dwarf, and very steady, with a watchmaker's loupe on a cord round one wrist. They are not a miner's hands any more. On the right palm there is an old callus, across the base of the fingers, the width of a small pick handle." },
        { name = "his chair", description = "Back to the wall. From it he can see the door, the stair, and every way out of the room. He chose it a thousand years ago and nobody else has ever sat in it." },
      },
      actions = {
        { "Sit with him", when = no(flag "fe_knows_pebble"),
          say "He nods. That is all. You drink beside him for a while, and it is companionable, and you leave knowing nothing more." },
        { "Ask about the breakthrough", when = all { flag "fe_knows_pebble", no(visited "sky_seam"), no(flag "fe_pebble_trusts") },
          say "His hand closes on the mug. \"You've been reading,\" he says. \"Reading's not seeing.\" And that is all you will get, until it isn't." },
        { "Tell him you have seen it", when = all { flag "fe_knows_pebble", visited "sky_seam", no(flag "fe_pebble_trusts") }, set "fe_pebble_trusts",
          say "You tell him about the cage, and the plank, and the blue. That you leaned out. He listens with his eyes shut. \"Was the cloud there?\" he says. \"Small one. Pink under.\" You say it was. He nods for a long time. \"A thousand years they've told me not to think about it. Kindly meant.\" He puts a key on the table, an iron one, small. \"Top of the stair behind the barrels. Go and look at what I did instead.\"" },
        { "Sit with him", when = all { flag "fe_knows_pebble", no(flag "fe_pebble_trusts") },
          say "You sit. He looks at you for a while, as a man looks who is deciding whether a clock is worth opening. \"Have you been down?\" he says at last. \"The Longshift. All the way.\" It is the only question he has." },
        { "Sit with him", when = flag "fe_pebble_trusts",
          say "He pushes the bowl of fried mushrooms an inch your way. From him that is a speech. \"Did you see the pick?\" he says after a while, to his mug. \"By the wall. I stood it up. I didn't like to leave it lying.\"" },
      } },
    { name = "the song",
      description = "It is called {i}The Digging of the Deep{/} and has four hundred verses, one for each fathom. They start it at the beginning of the evening.",
      things = {
        { name = "the first verse", description = "One dwarf, one pick, and a mountain that says no. The tune goes down a step at the end of every line. They all do." },
        { name = "a verse in the two hundreds", description = "It is about a flood, a pump, and a dwarf named Hask who held a valve shut with his beard. It has a second tune running under the first, for the pump." },
        { name = "the four-hundredth verse", description = "No words. They hum it, the whole hall, mugs down, looking at the table. It is the same tune as all the others, going down a step at the end of each line, until the last line, which stays where it is." },
      },
      actions = {
        { "Join in", say "You pick up the chorus, which is the word {i}down{/}, eleven times. On the twelfth they stop and you do not. It is, a neighbour explains, the verse where down runs out. Nobody sings that one. They hum it." },
      } },
    { name = "the landlord",
      icon = "☺",
      description = "Brewmaster Gram Stoutbarrow, who has a spare mug for you before you sit. It takes both hands. He is the ninth Stoutbarrow to keep the Second Shift and brews to the first one's recipe, which is carved on the cellar wall, and which he has never needed to read.",
      things = {
        { name = "his apron", description = "Leather, black with malt. The pocket holds a tap key, a bung mallet, and a spoon he does not lend." },
        { name = "his slate", description = "Every tab in the house. Dwarves pay at the turn of the century. The interest, he says, is that they have to look at it." },
      },
      actions = {
        { "Try the beer", say "It is black, bitter, warm, and has things in it to chew. By the bottom of the mug you understand the song. By the lid of the next you could not say what you understood." },
        { "Ask about Old Pebble", say "\"End table. Small mug. He's had the same seat since my nine-times-grandfather.\" He wipes the bar. \"Pays every century, on the day. Never sings. We don't press him.\" He looks down the hall, and wipes the same place again.",
          when = no(flag "fe_pick_returned") },
        { "Ask about Old Pebble", say "The landlord does not answer at once. He is listening to the end table. \"A thousand years,\" he says. \"I'd have said the voice would go, not used. It's kept.\" He blows his nose on the bar cloth, looks at it, and fetches another." },
        { "Ask for a room", say "\"There's the Tall Room,\" he says, with a showman's pause. \"Made up six hundred years. Never slept in. The king was carried home.\" He hangs a key back on its hook. \"Go up and look. If you can lie down in it without your feet in the passage, it's yours for nothing.\"" },
      } },
    { name = "the long tables",
      description = "Forty, of oak from the surface, each seating a shift. The benches are fixed. So, by custom, are the places, and a dwarf sits where his grandfather sat and puts his elbows in the same two dips.",
      things = {
        { name = "a table of miners", description = "Off shift, or in the case of the Longshift crew, off shift for a thousand years. It was their great-great-grandfathers' pit, and the pay has been kept up. They come in at the right hours on principle.",
          actions = {
            { "Ask when they go back", say "\"Soon,\" says the nearest, and the table nods. You have learned what the word weighs, down here, and do not ask again." },
          } },
        { name = "a table of smiths", description = "They have brought the beat with them. Forty mugs come down together between verses, and the smiths at the next table come down with them, and so on up the hall." },
        { name = "a table of clerks", description = "From the Hall of Grievances, in grey. They drink slowly and say little. Every other table has left a gap of one seat on each side of them, in case." },
        { name = "the elbow dips", description = "Two shallow hollows in the oak at every place, a forearm apart. At the end table, one place has only the right-hand dip. He has always held his mug with the left." },
        { name = "a carving under the table", description = "You drop your spoon and find it: a row of very small runes on the underside of the bench, at child height. A neighbour translates, and reddens. It is what the children think of the song." },
      } },
    { name = "the mugs",
      description = "Grey stone, turned on a lathe, a quart each, with a pewter lid. There are nine hundred, and each has a number and a regular.",
      things = {
        { name = "the lids", description = "Every mug has one, hinged. It is to keep the mountain out of the beer. The hinges are rejects from the Forge and the finest metalwork you have ever held." },
        { name = "the spoon", description = "It comes with the beer, standing up in it. It is for the bottom third. You are shown how." },
        { name = "the visitor's mug", description = "Number one. It hangs over the bar on a hook of its own, twice the size of the rest, with a handle a tall hand can get round. It was made for the king. It has been washed every day for six hundred years, and you are the second person to drink from it.",
          actions = {
            { "Read the base", say "You tip it, carefully, over your head. Runes, and under them, scratched with a ring: {i}Another. HRH.{/}" },
          } },
        { name = "the mug wall", description = "A rack behind the bar with nine hundred pegs. A dwarf's mug hangs there from his coming of age until his wake, when it is filled once more and stood at his place for the length of the song." },
      } },
    { name = "the bar",
      description = "A single slab of black granite, forty feet long, worn into a wave along the front by nine generations of leaning.",
      things = {
        { name = "the taps", description = "Three. {i}Black{/}, {i}Blacker{/}, and one with a small padlock on it and no label. The landlord says that one is for weddings, wakes, and the day the Longshift reopens." },
        { name = "a jar of pickled things", description = "Pale, round, in brine. Eggs, you decide. Then one of them turns over by itself, slowly, and you decide to leave the question open." },
        { name = "a bowl of fried mushrooms", description = "Salted, crisp, free, and refilled without being asked. This is how they get you onto the second mug." },
        { name = "the brass rail", description = "At dwarf foot height, which catches you across the shin. It is dented in forty places and every dent is the same depth." },
      } },
    { name = "the kitchen",
      description = "Through a hatch behind the bar: a range the width of the room, iron pans you could bathe in, and a cook with her beard in a net.",
      things = {
        { name = "the cook", description = "Ketta Panhandle, who has four dishes and has made each of them daily for ninety years. She looks at you through the hatch and adds a dumpling to something without being asked.",
          actions = {
            { "Ask what is good", say "\"All of it,\" she says. It is not a boast. She would not serve it otherwise. She would lodge a grievance against herself." },
          } },
        { name = "the stew pot", description = "Mushroom, barley, and the thing they call beef, cooked for a full shift. The spoon stands up in this as well. You begin to see a philosophy." },
        { name = "a rack of square loaves", description = "Dense, dark, baked in iron boxes. A dwarf loaf keeps for a month, travels down a mine in a pocket, and can be used, the cook says, to square up a shelf." },
        { name = "the dumplings", description = "Each the size of a fist and the weight of a small anvil. Three is a meal. The Longshift crew have four, on principle." },
        { name = "the kitchen cat", description = "There are no cats under the mountain. This is a cave weasel, white, long, asleep in a colander, which does the same job and is called the cat. It opens one pink eye at you and closes it." },
      } },
    { name = "the cellar stair",
      description = "A trap in the floor behind the bar, propped open. Cold comes up out of it, and the smell of malt.",
      things = {
        { name = "the tuns", description = "You can see them from the top step: nine vats of black oak, each the size of a house, in a row that goes back into the dark. The beer spends forty years in the first and is moved along. What comes out of the ninth is for the padlocked tap." },
        { name = "the recipe", description = "Carved on the cellar wall by the first Stoutbarrow, in runes a foot high. The last line, the landlord says, is not an ingredient. It reads {i}and do not hurry it{/}." },
        { name = "the yeast", description = "It lives in a stone crock on a shelf of its own and is older than the tavern. It has a name. It is consulted before any change to the menu." },
        { name = "a cellar beetle", description = "Black, glossy, as long as your thumb, walking along the rim of a tun. It lives on spilled malt, and walks in a slight curve." },
      } },
    { name = "the rooms upstairs",
      description = "A gallery round the hall with nine doors off it. Dwarf travellers are rare, since there is nowhere to come from, so the rooms are let by the century to bachelors and to husbands who have been asked to think about it.",
      things = {
        { name = "the Tall Room", description = "The ninth door, half as high again as the others. Inside: a bed seven feet long, a washstand at your waist, a chair you can sit in. It was built in a week for a king who never got up the stairs. The sheets are turned down. There is a mushroom on the pillow.",
          actions = {
            { "Lie down", say "Your feet stay inside the room. From the gallery the landlord shouts something, and the hall cheers, and a mug is hung on a new peg. You have, it appears, a room in Far Enough for nothing, for as long as you like. You lie and look at a ceiling that is the right distance away, and nearly weep." },
          } },
        { name = "a bachelor's door", description = "Boots outside, in a row, toes to the wall. Six pairs, all the same. He has one for each working day and a pair for best that have never been worn." },
        { name = "a door with a slate", description = "{i}Thinking about it. Day 4,112.{/} Under that, in another hand, a woman's: {i}And?{/}" },
      } },
    { name = "the barrels",
      key = "barrels",
      icon = "Θ",
      description = "Forty, each the size of a cottage, along the back wall. There is a stair behind them that goes up into the rock. The landlord says it's a store.",
      variants = {
        { when = flag "fe_pebble_trusts",
          description = "Forty, each the size of a cottage, along the back wall. Behind them, a narrow stair goes up into the rock. It is swept, and the lamp at the foot of it is lit. The landlord has always kept it lit. He does not say it's a store this time." },
      },
      actions = {
        { "Knock on one", say "It sounds full, and goes on sounding for some time. Forty dwarves turn to see who is checking the stock." },
      } },
    { name = "the hearth",
      description = "A fireplace you could stable a pony in, with a fire in it for the look of the thing. The heat comes from the Forge, through the floor. The fire is a quarter-share in a coal seam and a family tradition.",
      things = {
        { name = "the settle", description = "Stone, with cushions. This is where the oldest drinkers sit, and where the song is kept right: if a table goes wrong on a verse, a stick is rapped here and the whole hall goes back to the last chorus." },
        { name = "a poker", description = "Forge-made, with a ring handle. It is the wedding poker: a couple is not properly married until they have mulled a mug with it, together, without spilling. It is harder than it sounds and people practise." },
      } },
    { name = "a game of stones",
      description = "Two old dwarves and a ruled board, by the hearth. One of them has just moved. The other is going to think about it until Thursday.",
      actions = {
        { "Suggest a move", say "You point. Both of them look at the board, then at you, then at the board. \"That's what he did in my father's time,\" says one. \"Lost,\" says the other. They are not offended. You have joined a tradition." },
      } },
    { name = "the ceiling",
      description = "Low, vaulted, and black with nine generations of pipe smoke. You have hit it with the helmet four times. Each time a small cheer goes up and somebody chalks a mark on a beam.",
      things = {
        { name = "the beam with the marks", description = "A row of tallies under the heading {i}THE KING{/}, and a new, shorter row beside it under {i}THIS ONE{/}. You are eleven behind. They are rooting for you." },
      } },
    { name = "the skittle alley",
      description = "Down one side of the hall: a lane of polished slate, nine pins of bog oak and a ball of granite. The dwarves play in silence, measure the result with callipers, and enter it in a book.",
      things = {
        { name = "the score book", description = "Every game for eight hundred years. Every one is a draw. The lane is true, the pins are true and the players are dwarves. They play for the love of it, and in the hope." },
        { name = "the granite ball", description = "Worn to a perfect round by eight centuries of hands. It is checked for roundness on feast days. It has passed every time and each time there is a small cheer." },
      },
      actions = {
        { "Bowl a ball", say "It is heavier than it looks. Your ball goes down the lane on a curve that nobody in the hall has ever seen, takes the corner pin, the far pin and a mug off a table, and comes to rest in the hearth. There is a long silence. Then the landlord reaches for the book, turns to a clean page, and with enormous care rules a new column." },
      } },
    { name = "the pie hatch",
      description = "A slot in the wall with a shelf, from which pies come. Mushroom, mushroom and onion, and on feast days mushroom. Each is square. Each is stamped with its weight, which is the same.",
      actions = {
        { "Order a pie", say "A square pie comes through on a square plate. The crust rings when you tap it. Inside it is dark, rich and very good, and you say so. A voice from the hatch says, \"It's to specification,\" which you understand is how a dwarf blushes." },
      } },
  },

  exits = {
    { to = "plumb_square", description = "Out to the square, and air you do not have to chew." },
    { to = "pebble_room", label = "The stair behind the barrels",
      description = "Up a narrow stair into the rock, a long way, with a small iron key.",
      requires = flag "fe_pebble_trusts", hidden = true },
  },
}

space {
  id = "pebble_room",
  region = "far_enough",
  secret = true,
  wonder = true,
  name = "Pebble's Room",
  description = "A small room at the top of a long stair, high up inside the mountain, with a bed, a bench, and a wall of clocks. It is a watchmaker's room. He took up small work, after. In the far wall there is a round shutter of iron, the size of a plate, with a latch.",
  palette = { bg = "#0b0c14", text = "#cdd0dc", dim = "#62687e", accent = "#9fb4f0", border = "#30385c" },
  ambience = {
    shimmer { color = "#9fb4f0", strength = 0.14 },
    dust { glyphs = "·˙", color = "#4a5068", rate = 0.15, speed = 0.15 },
  },

  things = {
    { name = "the shutter",
      key = "shutter",
      wonder = true,
      icon = "◎",
      description = "Iron, round, oiled. {magic}There is light round the edge of it.{/}",
      variants = {
        { when = flag "fe_shutter_open",
          description = "Iron, round, oiled, and standing open. Through it there is daylight, and cold, and a piece of ordinary sky the size of a plate. {magic}He cut this himself, by hand, from the inside, through forty feet of mountain.{/} It took him two hundred years. He wanted one he could check the other against." },
      },
      things = {
        { name = "the view", visible_if = flag "fe_shutter_open",
          description = "You are looking out of the side of Old Grumble at about the height of the snow. Sky, with weather in it. A long way down, small and grey, the lake. The sky in the lake does not match the sky above it. He will have noticed that. He has had the time." },
        { name = "a hawk", visible_if = flag "fe_shutter_open",
          description = "Hanging on the wind, level with the hole, quite close. It turns its head and looks in at you. It has seen an old dwarf at this window every day of its life, and its mother's, and you are a change." },
        { name = "the tunnel of the hole", description = "Forty feet long, a plate wide, straight as a rule, cut with something small. You know with what. It was hung up again afterwards, he would have said. But it was never his to hang.",
          visible_if = flag "fe_shutter_open" },
        { name = "the latch", description = "A watchmaker's latch: it would hold against a gale and lifts with one finger." },
      },
      actions = {
        { "Open it", when = no(flag "fe_shutter_open"), set "fe_shutter_open", fx("wash", "#9fb4f0"),
          say "Blue. Not the blue under the mine: the top of it. You are looking out of the side of Old Grumble at an ordinary sky, with a hawk in it, and far below, small, the lake. He could not stop the mine going through into the one sky. So he came up here and cut a careful hole to the other, and for a thousand years he has had them both to compare. On the sill there is a notebook. It has two columns." },
        { "Put your face to it", when = flag "fe_shutter_open",
          say "Wind, real wind, with snow on it, and the smell of stone in the sun. After a day under the mountain it goes to your head like the black beer. You stay until your nose is numb." },
      } },
    { name = "the notebook",
      key = "notebook",
      visible_if = flag "fe_shutter_open",
      description = "On the sill, thick as a brick, the newest of many. Two columns, ruled by hand, headed in runes and, small, for his own practice, in letters: {i}above{/} and {i}below{/}.",
      things = {
        { name = "the column for above", description = "{i}Snow. Clear. Snow. Fog, lifting. Wind from the lake. Snow.{/} A thousand years of weather, a line a day, in a hand that starts round and young and gets smaller." },
        { name = "the column for below", description = "He went down, the first years, to look. Then he stopped needing to. In a thousand years of entries, one line a day, there is the one word: {i}evening{/}." },
        { name = "the earlier volumes", description = "Under the bed, in a row, three hundred of them, each dated on the spine. You open one from the middle. {i}Above: rain. Below: evening. Above: clear. Below: evening.{/} You open another. You stop opening them." },
        { name = "today's line", description = "{i}Above: snow, clearing.{/} And under {i}below{/}, the pencil has been set down on the page with the word not yet written. He was waiting for somebody to come up and tell him.",
          variants = {
            { when = flag "fe_pick_returned",
              description = "{i}Above: snow, clearing.{/} Under {i}below{/} he has been up since, and written it in: {i}evening{/}. And after it, for the first time in three hundred volumes, more words on the same line: {i}a tall one went and looked. Says the cloud is still there. Good.{/}" },
          } },
      },
      actions = {
        { "Read back a long way", say "You go back a hundred years, and two, and five. Above, the seasons turn over like pages. Below does not turn. It is as if one of the two skies were being lived in, and the other were being kept." },
      } },
    { name = "the outline on the wall",
      key = "pick outline",
      description = "Beside the bed, on a nail: nothing. Behind the nothing, painted on the plaster with a fine brush, the outline of a small pick. He did it himself, the way they do at the mine, so that there would be somewhere to hang it if anybody ever brought it back.",
      variants = {
        { when = flag "fe_pick_returned",
          name = "the pick on the wall",
          description = "Beside the bed, on its nail, inside its outline: a small pick with a pale ash handle. It does not quite fill the painted shape. He drew it from memory, and it had grown. Under it, since you hung it there, somebody has written one rune in pencil, with a hand that was not as steady as usual. You do not need it read to you." },
      },
      things = {
        { name = "the nail", description = "Forge-made, driven level, a thousand years ago, and never used. He dusts it." ,
          variants = {
            { when = flag "fe_pick_returned", description = "Forge-made, driven level, a thousand years ago. It is taking the weight as if it had only been waiting for the afternoon post." },
          } },
        { name = "the paint", description = "Touched up, over the years, wherever it flaked. There are a great many coats on that outline. It stands out from the wall." },
      },
      actions = {
        { "Hang up the pick", when = item "small_pick", take "small_pick", set "fe_pick_returned", fx "sparkle",
          say "You lift it onto the nail. It hangs straight. It does not quite fill the outline: he had remembered it bigger. You stand back. Down in the hall, forty feet of rock and a long stair below you, the song falters for a moment, as if somebody at the end table had stood up. Then you hear them move along a verse, to let him in." },
        { "Look at the empty place", when = all { no(item "small_pick"), no(flag "fe_pick_returned") },
          say "A nail, and an outline. Up at the Longshift there is a matching one on the tool wall, with {b}WHO.{/} chalked under it. The pick itself is neither place. You know where it is. You have stood next to it." },
      } },
    { name = "the wall of clocks",
      description = "Two hundred, all his, all going, none of them agreeing. He does not set them. He says he likes to hear time argued out.",
      things = {
        { name = "one stopped clock", description = "The only one not going. A miner's shift-watch, steel, with a cracked glass, stopped at the hour of the breakthrough. He did not stop it. It did that itself.",
          actions = {
            { "Wind it", say "The crown turns freely and takes nothing up. There is nothing wrong with the watch. He has had it apart forty times. It has decided what time it is." },
          } },
        { name = "a clock with one hand", description = "It goes round once a century. He made it to have something to look forward to." },
        { name = "a clock that runs backwards", description = "Carefully made, beautifully finished, and wrong on purpose. On the dial, in small runes: {i}in case{/}." },
        { name = "the smallest clock", description = "Set in the head of a nail. You hold your breath to hear it. It is the only one in the room that keeps the beat of the Great Forge, and it has never been adjusted." },
        { name = "the noise of them", description = "Two hundred ticks, no two together. After a minute it stops being a noise and becomes a kind of weather, a fine steady rain of time, and you understand how a person could sleep in it." },
      } },
    { name = "the workbench",
      description = "Lenses, tweezers, and a watch movement no bigger than a lentil. The apprentice with the small pick grew up to do small work.",
      things = {
        { name = "the movement", description = "Under a glass, half built. Wheels you can only see when they catch the light. It is for a watch that will go in a ring, he says, for the landlord's daughter, who is getting married in eighty years." },
        { name = "his loupes", description = "A row of nine, each stronger than the last. The ninth shows you the grain of your own thumb as a ploughed field." },
        { name = "a tray of screws", description = "Each smaller than a grain of salt, each with a slot. He cuts the slots himself. He says a bought screw is a stranger in the house." },
        { name = "a drawing, pinned up", description = "Plans for a clock with two faces, side by side, marked {i}above{/} and {i}below{/}. The first face has all its wheels drawn in. The second has a dial, a hand, and behind them nothing: no works, no spring. He has rubbed that half out many times. A clock that keeps one hour does not need to go." },
      } },
    { name = "the bed",
      description = "Narrow, short, and made so tightly that the blanket rings. He sleeps facing the shutter.",
      things = {
        { name = "the pillow", description = "Flat. On the wall above it, at the height where a sleeper's eyes would open, he has hung a small round mirror, angled to catch the first light round the edge of the shutter." },
        { name = "a pair of slippers", description = "Felt, mended at the toe. Under the mountain a dwarf goes in boots. These are for a floor with daylight on it." },
      } },
    { name = "the stair head",
      description = "The stair comes up through the floor, four hundred and six steps from the back of the barrels. He goes down it every evening and up it every night, and it has never occurred to anybody to say that it was too much for him.",
      things = {
        { name = "the rope rail", description = "On the wall side. Tarred hemp, coiled at the top by an expert. It is mine rope. He did not take it from a peg." },
      } },
    { name = "a kettle on a spirit lamp",
      description = "Forge-made, small, for one. Beside it there are two cups. One has never had tea in it. He washes it anyway, with the other.",
      variants = {
        { when = flag "fe_pick_returned",
          description = "Forge-made, small, for one. Beside it there are two cups, both washed, both upside down on the cloth, and both, you notice, still wet." },
      } },
    { name = "a snow finch",
      icon = "v",
      visible_if = flag "fe_shutter_open",
      description = "Brown and white, on the sill, eating crumbs from a saucer that was plainly put there for it. It has no fear of the room at all. It hops onto the notebook, onto the column for {i}above{/}, and looks at you from there.",
      actions = {
        { "Hold out a crumb", say "It considers your hand, and then takes the crumb from the saucer instead, which is the arrangement it has. But it stays." },
      } },
    { name = "the cold",
      description = "It is the only cold room in Far Enough. The warmth of the Forge does not come this high, and what comes round the shutter is mountain air. He likes it. He says it reminds him which way is out." },
    { name = "a jar of sky things",
      description = "On the sill, with a cloth over it. He lifts the cloth to show you, and puts it back at once. A leaf. A snail shell. A dead bee. A bit of blue eggshell. Things that came in at the shutter, or that he went out and got.",
      things = {
        { name = "the leaf", description = "Brown, curled, from some tree far down the mountain. A wind brought it. He has drawn it eleven times in the notebook and measured the stalk." },
        { name = "the bee", description = "On a pin. He does not know what it is for. He has a theory, which is nearly right, and involves the yellow dust on its legs." },
      },
      actions = {
        { "Tell him what a bee does", say "You explain: flowers, honey, the hive. He writes all of it down. He stops at the hive. \"A city,\" he says. \"With cells. All to a measure. And a queen. And every one of them goes {i}out{/}, every day, into that,\" he nods at the shutter, \"and comes home.\" He looks at the bee for a long time. \"Then it can be done,\" he says." },
      } },
    { name = "a coat on a peg",
      description = "Sheepskin, far too big, with the wool inside. He bought it from a monk at the top of the stair for nine hinges. He wears it to open the shutter. It is the only garment in Far Enough that was made for weather." },
  },

  exits = {
    { to = "beer_hall", label = "The stair down", description = "Four hundred and six steps, to warmth and the song." },
  },
}
